#!/usr/bin/env python3
# MEER v4.53 patch (HTML) — repo-form ship script.
# Local chain (tasalli-verified) ka repo roop: patch_v453_js ->
# patch_v453_ver. Har stage ka source NECHAY VERBATIM embedded hai
# (anchors/asserts bilkul wahi jo local built-v453-final.html
# (MD5 91ef15d0e21cb5699a0d71b808c05de3) banane me istemal hue).
# Stage feeding: dono stages argv lete hain — driver CI target ko
# temp dir me 'built-v452-final.html' ke naam se deta hai, jis se
# js stage ka MD5 guard (c23dfac7a908e4d459829e2ca997d494) bilkul
# local chain ki tarah fire hota hai; ver stage ka guard input ke
# NAAM ('built-v453.html') + us ki MD5 par fire hota hai.
# Chalana: repo root se  python3 patch_v453.py
# Target: android/app/src/main/assets/www/index.html (workflow ki
# "Sync web assets" + v389..v452 steps ke BAAD ki haalat par).
# Is version me manifest ki KOI tabdeeli nahi hai.
import hashlib
import subprocess
import sys
import tempfile
from pathlib import Path

ROOT = Path(__file__).resolve().parent
HP = ROOT / 'android/app/src/main/assets/www/index.html'

STAGES = [
    ('stage_js.py', '#!/usr/bin/env python3\n# MEER v4.53 JS patch — COMPOSE-HANG FIX (12-min deadline + segment\n# progress) — LOCAL ONLY (sim-meer2). GitHub upload / APK build is\n# patch ka kaam NAHI hai.\n#\n# BASE: built-v452-final.html (MD5 c23dfac7a908e4d459829e2ca997d494)\n# — v4.52 final. Base file kabhi modify NAHI hoti — copy par kaam\n# karke built-v453.html likhi jati hai.\n#\n# MASLA (Hamza ke phone ka saboot, 2026-10-23):\n#   v4.52 ka async compose chal to raha hai lekin agar Java taraf\n#   compose kahin atak jaye to JS ka poll 45 MINUTE tak intezar\n#   karta hai — screen par sirf "Video ban rahi hai… Ns" chalta\n#   rehta hai (raat bhar / 30 minute tak video nahi bani). Aur poll\n#   ke paas atak hue worker ko saaf karne ka koi raasta hi nahi.\n#\n# FIX (sirf v4.52 ke apne async block ke andar; baqi sab waisa hi):\n#   1. meerPollBridgeStatus ko ikhtiyari 3rd param (opts) mila:\n#      timeoutMs + onTimeout. Baghair opts wale callers (saare\n#      STAMP wale raste) ka behaviour harf-ba-harf waisa hi —\n#      45-minute default, koi reset nahi. Sirf COMPOSE wale dono\n#      poll (busy-wait + main) ab 12-minute limit lete hain aur\n#      timeout par Java ke naye resetComposeAsync() ko AIK dafa\n#      bulate hain (busy flag saaf + generation barh jati hai,\n#      atak hua worker apne agle check par khud ruk jata hai).\n#   2. meerComposeTick ab status string bhi leta hai: Java\n#      "running:<seg>/<total>" bheje to message me\n#      "(hissa <seg>/<total>)" jud jata hai. Purani "running"\n#      (baghair progress) par message bilkul waisa hi.\n#   Tick ka doosra argument purane callers ke liye mehfooz hai —\n#   poll ab tickFn(t0, st) bulata hai; stamp wale raste tickFn\n#   null hi rakhte hain.\n#\n# Har anchor assert hota hai; aakhir me strip-back proof: saari\n# tabdeeliyan ulta karne par base byte-identical wapas milti hai.\n\nimport hashlib\nimport sys\nfrom pathlib import Path\n\nHERE = Path(__file__).resolve().parent\nSRC = Path(sys.argv[1]) if len(sys.argv) > 1 else HERE / \'built-v452-final.html\'\nDST = Path(sys.argv[2]) if len(sys.argv) > 2 else HERE / \'built-v453.html\'\nassert SRC.resolve() != DST.resolve(), \'SRC aur DST aik nahi ho sakte — patch ROK diya\'\nif SRC.name == \'built-v452-final.html\':\n    md5 = hashlib.md5(SRC.read_bytes()).hexdigest()\n    assert md5 == \'c23dfac7a908e4d459829e2ca997d494\', f\'base MD5 galat: {md5} — patch ROK diya\'\n\nhtml = SRC.read_text(encoding=\'utf-8\')\norig = html\napplied = []\nundo = []  # (new, old) joray — strip-back proof ke liye\n\n\ndef rep(old, new, label, count=1):\n    global html\n    n = html.count(old)\n    assert n == count, f\'anchor [{label}] {n} dafa mila ({count} chahiye tha) — patch ROK diya\'\n    html = html.replace(old, new)\n    applied.append(label)\n    undo.append((new, old))\n\n\n# =====================================================================\n# 1) meerComposeTick — Java progress (hissa seg/total)\n# =====================================================================\nTICK_OLD = """function meerComposeTick(t0){\n  try{\n    var sec=Math.max(1,Math.round((Date.now()-t0)/1000));\n    var msg=\'⏳ Video ban rahi hai… \'+sec+\'s (app chalti rahegi, thora wait karo)\';\n    var ids=[\'realStat\',\'advStat\',\'suspStat\'];\n    for(var i=0;i<ids.length;i++){ var el=document.getElementById(ids[i]); if(el) el.textContent=msg; }\n  }catch(e){}\n}"""\nTICK_NEW = """function meerComposeTick(t0,st){\n  try{\n    var sec=Math.max(1,Math.round((Date.now()-t0)/1000));\n    var msg=\'⏳ Video ban rahi hai… \'+sec+\'s (app chalti rahegi, thora wait karo)\';\n    // v4.53: Java progress de (running:<seg>/<total>) to hissa bhi dikhao\n    var _pm=/^running:(\\\\d+)\\\\/(\\\\d+)$/.exec(st||\'\');\n    if(_pm) msg+=\' (hissa \'+_pm[1]+\'/\'+_pm[2]+\')\';\n    var ids=[\'realStat\',\'advStat\',\'suspStat\'];\n    for(var i=0;i<ids.length;i++){ var el=document.getElementById(ids[i]); if(el) el.textContent=msg; }\n  }catch(e){}\n}"""\nrep(TICK_OLD, TICK_NEW, \'J1 compose tick progress\')\n\n\n# =====================================================================\n# 2) meerPollBridgeStatus — ikhtiyari timeout/reset (opts)\n#    Default (stamp wale callers) bilkul purana: 45 min, koi reset nahi.\n# =====================================================================\nPOLL_OLD = """function meerPollBridgeStatus(statusFn,tickFn){\n  return new Promise(function(resolve){\n    var t0=Date.now();\n    var iv=setInterval(function(){\n      var st=\'\';\n      try{ st=statusFn()||\'\'; }catch(e){}\n      if(st.indexOf(\'done:\')===0){ clearInterval(iv); resolve({kind:\'done\',value:st.substring(5)}); }\n      else if(st.indexOf(\'error:\')===0){ clearInterval(iv); resolve({kind:\'error\',value:st}); }\n      else{\n        if(tickFn) tickFn(t0);\n        if(Date.now()-t0>45*60*1000){ clearInterval(iv); resolve({kind:\'error\',value:\'error:async_timeout\'}); }\n      }\n    },900);\n  });\n}"""\nPOLL_NEW = """function meerPollBridgeStatus(statusFn,tickFn,opts){\n  return new Promise(function(resolve){\n    var t0=Date.now();\n    var limit=(opts&&opts.timeoutMs)?opts.timeoutMs:45*60*1000;\n    var iv=setInterval(function(){\n      var st=\'\';\n      try{ st=statusFn()||\'\'; }catch(e){}\n      if(st.indexOf(\'done:\')===0){ clearInterval(iv); resolve({kind:\'done\',value:st.substring(5)}); }\n      else if(st.indexOf(\'error:\')===0){ clearInterval(iv); resolve({kind:\'error\',value:st}); }\n      else{\n        if(tickFn) tickFn(t0,st);\n        if(Date.now()-t0>limit){ clearInterval(iv); if(opts&&opts.onTimeout){ try{ opts.onTimeout(); }catch(e){} } resolve({kind:\'error\',value:\'error:async_timeout\'}); }\n      }\n    },900);\n  });\n}"""\nrep(POLL_OLD, POLL_NEW, \'J2 poll opts (timeout/reset)\')\n\n\n# =====================================================================\n# 3) Compose poll ka opts helper — insertion (meerComposeNativeAsync\n#    se pehle). 12-minute limit + timeout par resetComposeAsync AIK\n#    dafa (naya bridge na ho to khamoshi se skip — purana build safe).\n# =====================================================================\nHELPER = """// v4.53: COMPOSE poll ke liye 12-minute deadline — atak jaye to\n// Java worker ko reset karke saaf karo (stamp wale raste is se\n// bilkul alag, un ka 45-minute wala purana behaviour hi rehta hai).\nfunction meerComposePollOpts(){\n  return {timeoutMs:12*60*1000, onTimeout:function(){ try{ if(typeof RealClipBridge!==\'undefined\'&&RealClipBridge&&typeof RealClipBridge.resetComposeAsync===\'function\') RealClipBridge.resetComposeAsync(); }catch(e){} }};\n}\n"""\nrep(\'async function meerComposeNativeAsync(segmentsJson,fileName){\',\n    HELPER + \'async function meerComposeNativeAsync(segmentsJson,fileName){\',\n    \'J3 compose poll opts helper\')\n\n\n# =====================================================================\n# 4) Dono COMPOSE poll calls ko opts do (busy-wait + main poll).\n#    Stamp wale calls (MeerMediaBridge...) bilkul nahi chhedte.\n# =====================================================================\nrep(\'meerPollBridgeStatus(function(){ return RealClipBridge.composeAsyncStatus(); },meerComposeTick)\',\n    \'meerPollBridgeStatus(function(){ return RealClipBridge.composeAsyncStatus(); },meerComposeTick,meerComposePollOpts())\',\n    \'J4 compose polls ko 12-min opts\', count=2)\n\n\n# ---------- Aakhri asserts ----------\n# Timeout ke alfaaz: purana default 1 dafa (poll), naya 1 dafa (helper)\nassert html.count(\'45*60*1000\') == 1, \'stamp default 45-min badal gaya — patch ROK diya\'\nassert html.count(\'12*60*1000\') == 1, \'12-min compose timeout ghalat tadaad me — patch ROK diya\'\nassert html.count(\'resetComposeAsync\') == 2, \'resetComposeAsync sirf helper me hona chahiye (typeof + call)\'\nassert html.count(\'function meerComposePollOpts(){\') == 1\nassert html.count(\'(hissa \') == 1, \'progress format ghalat tadaad me\'\n# Stamp wale poll calls harf-ba-harf waisay hi (2 stamp + 2 stampMove)\nassert html.count(\'meerPollBridgeStatus(function(){ return MeerMediaBridge.stampAsyncStatus(); },null)\') == 2\nassert html.count(\'meerPollBridgeStatus(function(){ return MeerMediaBridge.stampMoveAsyncStatus(); }, null)\') == 2\n# Sync fallback + baqi flow bilkul waisa hi\nassert html.count(\'function meerComposeFlow(segments,fileName,mood){\') == 1\nassert html.count(\'await meerComposeFlowAsync(\') == 9\n# Strip-back proof: saari tabdeeliyan ulta karne par base wapas\nchk = html\nfor new, old in reversed(undo):\n    assert chk.count(new) >= 1, f\'strip-back: naya hissa nahi mila: {new[:60]}\'\n    chk = chk.replace(new, old, 1) if new != old else chk\n# J4 do dafa laga tha — us ka doosra nishan bhi ulta karo\nchk = chk.replace(\n    \'meerPollBridgeStatus(function(){ return RealClipBridge.composeAsyncStatus(); },meerComposeTick,meerComposePollOpts())\',\n    \'meerPollBridgeStatus(function(){ return RealClipBridge.composeAsyncStatus(); },meerComposeTick)\')\nassert chk == orig, \'strip-back FAIL — tabdeeli ke ilawa bhi kuch badla\'\n\nDST.write_text(html, encoding=\'utf-8\')\nprint(\'applied:\', \', \'.join(applied))\nprint(\'WROTE\', DST, f\'({len(html)} chars; base se {len(html) - len(orig):+d})\')\nprint(\'MD5:\', hashlib.md5(DST.read_bytes()).hexdigest())\n'),
    ('stage_ver.py', '#!/usr/bin/env python3\n# MEER v4.53 VERSION patch — sirf version pehchan 4.52 -> 4.53 — LOCAL ONLY\n# (sim-meer2). GitHub upload / APK build is patch ka kaam NAHI hai.\n#\n# BASE: built-v453.html (MD5 b28f0f9bd1ee0648d2960e4cdb2111fe) —\n# v4.53 JS stage ki output (compose deadline + progress). Base file\n# kabhi modify NAHI hoti — copy par kaam karke built-v453-final.html\n# likhi jati hai.\n#\n# Sirf teen user-visible/functional version strings badalte hain,\n# bilkul v4.51/v4.52 wale tareeqe se (full anchors, exactly-once\n# assert). Code comments me maujood "v4.52" wale alfaaz NAHI\n# chhoote (wo pichle rounds ke record hain) — is liye koi global\n# count assert nahi, sirf anchors.\n\nimport hashlib\nimport sys\nfrom pathlib import Path\n\nHERE = Path(__file__).resolve().parent\nSRC = Path(sys.argv[1]) if len(sys.argv) > 1 else HERE / \'built-v453.html\'\nDST = Path(sys.argv[2]) if len(sys.argv) > 2 else HERE / \'built-v453-final.html\'\nassert SRC.resolve() != DST.resolve(), \'SRC aur DST aik nahi ho sakte — patch ROK diya\'\nif SRC.name == \'built-v453.html\':\n    md5 = hashlib.md5(SRC.read_bytes()).hexdigest()\n    assert md5 == \'b28f0f9bd1ee0648d2960e4cdb2111fe\', f\'base MD5 galat: {md5} — patch ROK diya\'\n\nhtml = SRC.read_text(encoding=\'utf-8\')\norig = html\napplied = []\n\n\ndef rep(old, new, label):\n    global html\n    n = html.count(old)\n    assert n == 1, f\'anchor [{label}] {n} dafa mila (1 chahiye tha) — patch ROK diya\'\n    html = html.replace(old, new)\n    applied.append(label)\n\n\n# ---------- Version strings: 4.52 -> 4.53 ----------\nrep(\'const APP_VER="4.52";\',\n    \'const APP_VER="4.53";\',\n    \'V1 APP_VER\')\n\nrep(\'>v4.52 MEER • 100% Free • No watermark<\',\n    \'>v4.53 MEER • 100% Free • No watermark<\',\n    \'V2 footer\')\n\nrep(\'id="verLabel" style="opacity:.6;font-size:12px">v4.52<\',\n    \'id="verLabel" style="opacity:.6;font-size:12px">v4.53<\',\n    \'V3 verLabel static\')\n\n# ---------- Aakhri asserts ----------\nassert html.count(\'const APP_VER="4.53";\') == 1\nassert html.count(\'const APP_VER="4.52"\') == 0\nassert html.count(\'v4.53 MEER\') == 1 and html.count(\'v4.52 MEER\') == 0\nassert html.count(\'id="verLabel" style="opacity:.6;font-size:12px">v4.53<\') == 1\nassert len(html) == len(orig), \'lambai badli — sirf 4.52->4.53 (barabar size) hona chahiye tha\'\n\nDST.write_text(html, encoding=\'utf-8\')\nprint(\'applied:\', \', \'.join(applied))\nprint(\'WROTE\', DST, f\'({len(html)} chars)\')\nprint(\'MD5:\', hashlib.md5(DST.read_bytes()).hexdigest())\n'),
]


def run_stage(tmp, name, source, args=(), cwd=None):
    f = tmp / name
    f.write_text(source, encoding='utf-8')
    print(f'--- v4.53 stage {name} ---', flush=True)
    subprocess.run([sys.executable, str(f), *[str(a) for a in args]],
                   cwd=str(cwd or tmp), check=True)


def main():
    assert HP.is_file(), f'target nahi mila: {HP} — patch ROK diya'
    original = HP.read_bytes()
    with tempfile.TemporaryDirectory() as td:
        tmp = Path(td)
        stages = dict(STAGES)
        # Stage 1: js — argv SRC/DST; SRC ka naam
        # 'built-v452-final.html' hote hi us ka MD5 guard fire hoga.
        (tmp / 'built-v452-final.html').write_bytes(original)
        run_stage(tmp, 'stage_js.py', stages['stage_js.py'],
                  (tmp / 'built-v452-final.html', tmp / 'built-v453.html'))
        # Stage 2: version — argv SRC/DST; SRC ka naam
        # 'built-v453.html' hote hi us ka MD5 guard fire hoga.
        run_stage(tmp, 'stage_ver.py', stages['stage_ver.py'],
                  (tmp / 'built-v453.html', tmp / 'built-v453-final.html'))
        final = (tmp / 'built-v453-final.html').read_bytes()
    fmd5 = hashlib.md5(final).hexdigest()
    assert fmd5 == '91ef15d0e21cb5699a0d71b808c05de3', \
        f'final MD5 galat: {fmd5} — patch ROK diya (kuch nahi likha)'
    HP.write_bytes(final)
    print(f'v4.53 patch done: {HP} ({len(original)} -> {len(final)} bytes)')


if __name__ == '__main__':
    main()
